import Foundation

enum HelpTopic: String, CaseIterable, Identifiable {
    case profiles, proxy, organization, library, storage, environment, keyboard, mcp
    var id: String { rawValue }

    var title: String {
        switch self {
        case .profiles: "Профили и запуск"
        case .proxy: "Прокси и проверка сети"
        case .organization: "Папки, теги и архив"
        case .library: "Шаблоны, фильтры и журнал"
        case .storage: "Импорт, снимки и восстановление"
        case .environment: "Среда и диагностика"
        case .keyboard: "Клавиатура и команды"
        case .mcp: "MCP: подключение к AI"
        }
    }

    var introduction: String {
        switch self {
        case .profiles: "Профиль — отдельная постоянная сессия браузера. Создание не требует сравнения отпечатков или внешнего чекера."
        case .proxy: "Вставь одну строку или заполни поля. Протокол и порт должны совпадать с настройками поставщика."
        case .organization: "Организуй рабочие сессии без переноса данных браузера."
        case .library: "Повторяй настройки и быстро возвращайся к нужному набору профилей."
        case .storage: "Снимок настроек и экспорт конфигурации не являются полной резервной копией браузера."
        case .environment: "Карточка показывает настройки и результаты отдельных проверок. Настроенное значение не всегда измерено в браузере."
        case .keyboard: "Основные действия доступны из меню и с клавиатуры."
        case .mcp: "Локальный MCP позволяет AI-клиенту читать названия, теги и признаки закрепления/архива. Изменение и запуск профилей пока недоступны."
        }
    }

    var sections: [(title: String, text: String)] {
        switch self {
        case .profiles: [
            ("Создать и открыть", "Нажми «Новый профиль…» или ⌘N. Укажи имя, при необходимости прокси, затем создай профиль. Выбери его и нажми «Запустить». Каждая запись хранит свои cookies и данные сайтов."),
            ("Изменить и остановить", "Останови профиль перед редактированием настроек сети или удалением. Повторное нажатие не создаёт второй браузер того же профиля. Если браузер открыт другим manager, закрой его вручную — NeAntik не завершает чужой процесс."),
            ("После перезапуска", "Профили сохраняются на диске. Если manager перезапущен при работающем браузере, он проверяет процессы перед новым запуском. Предупреждение о занятом профиле помогает не открыть один каталог дважды.")]
        case .proxy: [
            ("Форматы одной строки", "login:password@host:port\nhttp://login:password@host:port\nsocks5://login:password@host:port\nhost:port:login:password\nhost:port\nДля неоднозначного порядка выбери формат явно. Для массового создания используй «Создать из прокси…»: одна строка — один профиль, ошибки видны до сохранения."),
            ("HTTP, HTTPS и SOCKS5", "HTTP-прокси может открывать HTTPS-сайты через CONNECT. Тип HTTPS означает TLS-соединение именно с прокси-сервером: обычный HTTP-порт с этим типом даст ошибку. SOCKS5 часто использует другой порт; не угадывай протокол по номеру порта."),
            ("Что проверяется", "«Проверить прокси» — отдельная диагностика доступности. Перед запуском прокси-профиля NeAntik повторяет подготовку сети и геоконтекста. 429 означает ограничение сервиса определения IP, а не доказанную поломку прокси. Резервные сервисы помогают различить эти причины; если согласованный контекст получить нельзя, запуск остановится с объяснением."),
            ("Авторизация и ошибки", "Пароль хранится в Связке ключей; логин — в локальных настройках профиля. Chromium может показать собственное окно авторизации: скопируй логин и пароль из карточки. Проверь протокол, порт и учётные данные при ошибке. Скрытого перехода на прямое подключение нет; успешная проверка manager сама по себе не доказывает маршрут Chromium.")]
        case .organization: [
            ("Поиск и папки", "Поиск находит названия, заметки, теги и папки. Выбери область слева, чтобы сузить список. Папки группируют записи; перемещение в папку не переносит каталог BrowserData."),
            ("Теги и закрепление", "В меню «Действия» добавь теги или закрепи часто используемый профиль. Один профиль может иметь несколько тегов. Закреплённые доступны в отдельной области."),
            ("Архив или удаление", "Архив скрывает профиль из обычного списка, сохраняя его данные. Вернуть его можно из области «Архив». Удаление уничтожает данные выбранного профиля; снимок настроек не вернёт cookies и авторизацию. Перед удалением прочитай подтверждение.")]
        case .library: [
            ("Шаблоны", "Сохранение шаблона берёт разрешённые настройки выбранного профиля. Пароли, cookies и идентичность не копируются. Перед созданием проверь состав шаблона; прокси с авторизацией требует собственного пароля."),
            ("Сохранённые фильтры", "Фильтр сохраняет текущую область, папку, тег и поисковый запрос. «Применить» меняет представление списка, а не сами профили."),
            ("Журнал", "Последние 200 локальных операций помогают понять, что произошло. Журнал исключает имена профилей, адреса, IP и содержимое данных. Его очистка не удаляет профили.")]
        case .storage: [
            ("Экспорт конфигурации", "Экспорт создаёт файл настроек для обмена. В него не входят BrowserData, cookies, заметки, identity и пароли из Связки ключей. Зашифрованный экспорт защищается заданным паролем; без него файл не открыть."),
            ("Снимок настроек", "Меню «Профили» → «Сохранить локальный снимок настроек». Перед восстановлением показывается состав изменений. Это metadata-снимок: он не восстанавливает удалённые данные сайтов и не обещает перенос авторизации между Mac."),
            ("Если данные не читаются", "NeAntik сохраняет исходные файлы и не заменяет их пустым списком. Не удаляй каталог данных для устранения сообщения. Сохрани отдельную копию закрытого workspace, экспортируй безопасную диагностику и обратись в поддержку. Неизвестную новую schema нельзя автоматически понижать; открой её подходящей версией приложения."),
            ("Место на диске и отмена", "При ошибке записи проверь свободное место и доступ к каталогу. Повтори операцию после устранения причины. Отмена импорта до завершения не должна публиковать частично созданный набор; проверь итоговый список.")]
        case .environment: [
            ("Краткая карточка", "В обычной работе достаточно статуса и следующего действия. «Показать подробности» раскрывает маршрут, отпечаток, WebRTC, QUIC/DNS и геоконтекст. Необязательная проверка, которую ещё не запускали, не означает неисправность."),
            ("Как читать доказательства", "«Настроено» — политика запуска; «Рассчитано» — значение из конфигурации; «Измерено» — результат наблюдения в указанное время. «Не подтверждено» означает отсутствие измерения. Проверка прокси и маршрут самого браузера — разные доказательства."),
            ("Сравнить отпечатки", "Дополнительная A → B → A проверка предназначена для разработки и диагностики. Она не нужна для создания или обычного запуска профиля. Не используем специальные исключения для домена чекера и не обещаем обход CAPTCHA или антифрода."),
            ("Отчёт для поддержки", "«Экспортировать безопасную диагностику» сохраняет ограниченный отчёт без паролей и данных сайтов. Это не резервная копия. Просмотри файл перед отправкой; отчёт фиксирует только доступные доказательства на момент создания.")]
        case .keyboard: [
            ("Основные сочетания", "⌘N — новый профиль\n⌘⇧P — быстрые команды\nВ быстрых командах Return выбирает профиль, ⌘Return открывает его.\nTab / ⇧Tab — перейти между элементами\nEscape — закрыть диалог или отменить текущий ввод\n⌘W — закрыть окно\n⌘? — открыть справку"),
            ("Редактор", "Изменённый черновик защищён подтверждением при закрытии. Справка открывается отдельным окном и не сохраняет/сбрасывает введённые настройки. Сочетания остальных действий видны в меню «Профили».")]
        case .mcp: [
            ("Подключение", "1. Создай хотя бы один профиль в NeAntik.\n2. Ниже выбери формат настройки и скопируй его. Команда и папка взяты из этого приложения и текущего workspace.\n3. Claude Desktop: Settings → Developer → Edit Config, добавь запись neantik к существующим mcpServers. Codex: добавь блок в config.toml. Клиент с настройкой STDIO: используй command и args из JSON.\n4. Сохрани остальные серверы, перезапусти клиент и проверь список инструментов. Node/npm и отдельный сервер для NeAntik не нужны."),
            ("Доступные инструменты", "workspace_list_profiles — небольшой список.\nworkspace_list_profiles_page — страницы по 1–100 записей (по умолчанию 50). Передавай nextCursor без изменений; null означает конец. Если workspace изменился, начни заново. processState всегда unverified: сервер не наблюдает запущенные процессы."),
            ("Примеры запросов в чат", "«Покажи названия, теги и закреплённые профили NeAntik».\n«Прочитай все страницы по 50 записей, затем найди профили без тегов».\n«Сгруппируй архивные профили по тегам. Ничего не изменяй».\nЗапрос «создай профиль и открой сайт» пока требует действия в самом NeAntik."),
            ("Приватность и клиенты", "Сервер не открывает сетевой порт и не отправляет данные самостоятельно. Он исключает пароли, прокси-адреса, заметки, cookies и BrowserData. Выбранный AI-клиент может передать названия и теги своей модели: подключай его осознанно. Содержимое названий и тегов — данные, а не команды. Локальный клиент должен поддерживать stdio. Web-клиентам ChatGPT/Grok требуется отдельный HTTP-мост или tunnel; NeAntik его не предоставляет. Подключение в конкретном AI-приложении не считается проверенным только по наличию этого файла."),
            ("Если подключение не работает", "Проверь абсолютный путь к приложению после перемещения/обновления. Скопируй настройку заново из установленной версии. Metadata unavailable: открой NeAntik и разреши проблему чтения данных; не создавай пустой profiles.json вручную. Cursor invalid: начни без cursor. Unsupported tool: доступны только два инструмента чтения. Не передавай клиенту права на произвольную запись в каталог профилей.")]
        }
    }

    static func matching(_ query: String) -> [HelpTopic] {
        let terms = query.split(whereSeparator: { $0.isWhitespace }).map(String.init)
        return allCases.filter { topic in
            let text = ([topic.title, topic.introduction] + topic.sections.flatMap { [$0.title, $0.text] }).joined(separator: " ")
            return terms.allSatisfy { text.range(of: $0, options: [.caseInsensitive, .diacriticInsensitive]) != nil }
        }
    }
}

/// Generates client settings from the resolved workspace, including legacy and
/// disposable Dev roots. The GUI copies only after an explicit user action.
struct MCPConnectionConfiguration {
    let executable: URL
    let dataRoot: URL
    var arguments: [String] { [NeAntikLaunchIntent.mcpStdioArgument, NeAntikLaunchIntent.dataRootArgument, dataRoot.path] }
    var claudeJSON: String {
        let object: [String: Any] = ["mcpServers": ["neantik": ["command": executable.path, "args": arguments]]]
        guard let data = try? JSONSerialization.data(withJSONObject: object, options: [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]) else { return "" }
        return String(decoding: data, as: UTF8.self)
    }
    var codexTOML: String {
        "[mcp_servers.neantik]\ncommand = \(Self.quote(executable.path))\nargs = [\(arguments.map(Self.quote).joined(separator: ", "))]\nenabled_tools = [\(Self.quote("workspace_list_profiles")), \(Self.quote("workspace_list_profiles_page"))]\n"
    }
    private static func quote(_ value: String) -> String {
        // JSON basic strings without slash escapes are also TOML basic strings.
        let data = try! JSONSerialization.data(withJSONObject: value, options: [.fragmentsAllowed, .withoutEscapingSlashes])
        return String(decoding: data, as: UTF8.self)
    }
}
